function Base.show(io::IO, hmb::HMB)
    println(io, "HMB index with $(hmb.K) DMUs")
    println(io, "  Input distance functions: $(typeof(hmb.In0))")
    println(io, "  Output distance functions: $(typeof(hmb.Out0))")
  end

  function Base.getindex(hmb::HMB, i::Int)
    if i < 1 || i > hmb.K
      throw(BoundsError(hmb, i))
    end
    return (hmb.In0[i], hmb.In1[i], hmb.Out0[i], hmb.Out1[i])
  end

  function Base.length(hmb::HMB)
    return hmb.K
  end

  function Base.iterate(hmb::HMB, state=1)
    if state > hmb.K
      return nothing
    end
    return (hmb[state], state+1)
  end

  function Base.eltype(::Type{HMB{S,T}}) where {S,T}
    return Tuple{typeof(S), typeof(T)}
  end

  function Base.size(hmb

function (src::HMB)(i::Int64)
    return (src.Out1(i)/src.Out0(i))/(src.In1(i)/src.In0(i))
end

function (src::HMB)(i::Int64,j::Int64)
    return (src.Out1(i)/src.Out0(j))/(src.In1(i)/src.In0(j))
end

function (src::HMB)()
    return [src(i) for i in 1:src.K]
end

# Outer constructor for HMB
function HMB{S,T}(X0::Array,Y0::Array,X1::Array,Y1::Array) where {S<:AbstractDataEnvelopment,T<:RS}
  return HMB{S,T}(X0,Y0,X1,Y1)
end

# Outer constructor without explicit type parameters
function HMB(X0::Array,Y0::Array,X1::Array,Y1::Array,tech::Type{S}=Convex,RS::Type{T}=VRS) where {S<:AbstractDataEnvelopment,T<:RS}
  return HMB{S,T}(X0,Y0,X1,Y1)
end

# Calculate the index for all DMUs
function evaluate(hmb::HMB)
  return [hmb[i] for i in 1:hmb.K]
end

# Indexing into the HMB struct to get the index for a particular DMU
