function magnitudeProportionality(magnitude::Float64)

    forceMagnitude = 0.0

    # Distance Far
    @inbounds distanceFar = JuliaFuzzy.Variables.defuzzify(magnitude, slopeDistanceFar, inflectionDistanceFar)

    # Angle Big
    @inbounds angleBig = JuliaFuzzy.process(magnitude, meanAngleBig, standardDeviationAngleBig)

    # Velocity Slow
    @inbounds velocitySlow = JuliaFuzzy.Variables.defuzzify(magnitude, slopeVelocitySlow, inflectionVelocitySlow)

    # Distance Near
    @inbounds distanceNear = JuliaFuzzy.Variables.defuzzify(magnitude, slopeDistanceNear, inflectionDistanceNear)

    # Angle Little
    @inbounds angleLittle = JuliaFuzzy.process(magnitude, meanAngleLittle, standardDeviationAngleLittle)

    # Velocity Fast
    @inbounds velocityFast = JuliaFuzzy.Variables.defuzzify(magnitude, slopeVelocityFast, inflectionVelocityFast)

    # Aggregation
    @inbounds low = max(distanceFar, angleBig, velocitySlow)
    @inbounds high = min(distanceNear, angleLittle

