func (layer2Interface *Layer2Interface) BeforeSave(tx *gorm.DB) error {
	// Check if referenced Host exists
	if layer2Interface.HostID != 0 {
		host := &Host{}
		if err := tx.First(host, layer2Interface.HostID).Error; err != nil {
			return err
		}
		layer2Interface.Host = host
	}

	// Check if referenced Vlan exists
	if layer2Interface.VlanID != 0 {
		vlan := &Vlan{}
		if err := tx.First(vlan, layer2Interface.VlanID).Error; err != nil {
			return err
		}
		layer2Interface.Vlan = vlan
	}

	return nil
}

