func createServerMux() *http.ServeMux {
	serveMux := http.NewServeMux()
	// handle "/" pattern
	serveMux.HandleFunc("/", handleRootPath)
	return serveMux
}

func handleRootPath(resp http.ResponseWriter, req *http.Request) {
	fmt.Fprintln(resp, "proto:", strconv.Quote(req.Proto))
	fmt.Fprintln(resp, "host:", strconv.Quote(req.Host))
	fmt.Fprintln(resp, "URI:", strconv.Quote(req.RequestURI))
	fmt.Fprintln(resp, "method:", strconv.Quote(req.Method))
	fmt.Fprintln(resp, "content length:", req.ContentLength)
	fmt.Fprintln(resp, "UserAgent:", strconv.Quote(req.UserAgent()))
	fmt.Fprintln(resp, "Headers:")
	for key, values := range req.Header {
		for _, value := range values {
			fmt.Fprintf(resp, "\t%s: %s\n", key, strconv.Quote(value))
		}
	}
	fmt.Fprintln(resp, "Cookies:")
	for _, cookie := range req.Cookies() {
		fmt.Printf("\t%s\n", cookie)
	}
	fmt.Fprintln(resp, "Referer:", strconv.Quote(req.Referer()))
	fmt.Fprintln(resp, "remote addr:", strconv.Quote(req.RemoteAddr))
	fmt.Fprintf(resp, "\n\n\n\n%s", "Hello world from HTTP Server using Golang!!!")
}

