func (c *controller) deleteFromStore(kvObject datastore.KV) error {
	if kvObject.Skip() {
		return nil
	}
	cs := c.getStore(kvObject)
	return cs.DeleteObjectAtomic(kvObject)
}

func (c *controller) getStore(kvObject datastore.KV) datastore.DataStore {
	if kvObject.IsGlobal() {
		c.Lock()
		store := c.globalStore
		c.Unlock()
		return store
	}
	c.Lock()
	store := c.localStore
	c.Unlock()
	return store
}

