func (c *Client) Handshake() error {
	buf := make([]byte, 1+4+32) // version(1) + device_info_len(4) + user_id(32)
	_, err := io.ReadFull(c.conn, buf)
	if err != nil {
		return err
	}

	version := buf[0]
	if version != 1 {
		return errors.New("unsupported version")
	}

	deviceInfoLen := binary.BigEndian.Uint32(buf[1:5])
	if deviceInfoLen > 1024 {
		return errors.New("device info too long")
	}

	c.UserId = *(*[32]byte)(buf[5:37])

	if deviceInfoLen > 0 {
		c.DeviceInfo = make([]byte, deviceInfoLen)
		_, err = io.ReadFull(c.conn, c.DeviceInfo)
		if err != nil {
			return err
		}
