// Root returns the root directory of the repository.
func (r *Repository) Root() string {
	return r.root
}

// Close releases any resources held by the repository.
func (r *Repository) Close() error {
	return r.Lock.Close()
}

// ObjectPath returns the path to the object with the given digest.
func (r *Repository) ObjectPath(digest Digest) string {
	s := digest.String()
	return filepath.Join(r.root, "objects", s[:2], s[2:])
}

// GetObject returns a reader for the object with the given digest.
func (r *Repository) GetObject(digest Digest) (io.ReadCloser, error) {
	path := r.ObjectPath(digest)
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, ErrObjectNotFound
		}
		return nil, err
	}
	return f, nil
}

