		if err != nil {
			return nil, fmt.Errorf("unable to store header for directory entry %q: %s", entryName, err)
		}

		entry := DirectoryEntry{
			Name:         entryName,
			Type:         header.DirentType(),
			HeaderDigest: headerDescriptor.Digest(),
			HeaderSize:   headerDescriptor.Size(),
		}

