func NewCommandBridge(cmd Command) *cli.Command {
	return &cli.Command{
		Name:               cmd.name,
		Short:              i18n.T(cmd.shortEn, cmd.shortCn),
		Usage:              cmd.usage,
		Run:                runCommandBridge(cmd),
		EnableUnknownFlag:  true,
		SkipFlagParsing:    cmd.skipFlagParsing,
		Hidden:             cmd.hidden,
		Category:           cmd.category,
		Long:               i18n.T(cmd.longEn, cmd.longCn),
		SuggestFor:         cmd.suggestFor,
		Example:            cmd.example,
	}
}

